        private LocatorSignalRow Current { get { return _signalList.SelectedItem as LocatorSignalRow; } }
        private ToggleButton FilterButton(string text) { ToggleButton button = new ToggleButton { Content = text, Height = 34, Style = SegmentStyle(), Margin = new Thickness(0), Cursor = Cursors.Hand }; button.Click += (s, e) => { _filterMode = text; _allFilter.IsChecked = ReferenceEquals(button, _allFilter); _selectedFilter.IsChecked = ReferenceEquals(button, _selectedFilter); _judgedFilter.IsChecked = ReferenceEquals(button, _judgedFilter); _view.Refresh(); }; return button; }
        private bool FilterSignal(object value) { LocatorSignalRow row = value as LocatorSignalRow; if (row == null) return false; string search = _search.Text == "搜索信号名称" ? string.Empty : (_search.Text ?? string.Empty).Trim(); bool matches = search.Length == 0 || (row.Name + " " + row.OffsetText + " " + row.DataType).IndexOf(search, StringComparison.OrdinalIgnoreCase) >= 0; return matches && (_filterMode == "全部" || _filterMode == "已选" && row.Use || _filterMode == "有判断" && row.Use && row.NeedsJudgment); }
        private void RowPropertyChanged(object sender, PropertyChangedEventArgs e) { LocatorSignalRow row = sender as LocatorSignalRow; if (_singleMode && e.PropertyName == "Use" && row != null && row.Use) { foreach (LocatorSignalRow other in _rows.Where(value => value != row && value.Use)) other.Use = false; } RefreshFooter(); if (e.PropertyName == "ResultMode") RefreshDetailState(); if (_filterMode != "全部") _view.Refresh(); }
        private void SignalSelectionChanged(object sender, SelectionChangedEventArgs e) { if (_details == null) return; _details.DataContext = Current; RefreshDetailState(); }
        private void RefreshDetailState() { LocatorSignalRow row = Current; bool has = row != null; _details.IsEnabled = has; _updating = true; _needsJudgment.IsChecked = has && row.NeedsJudgment; _informationMode.IsChecked = has && row.ResultMode == "只记录信息"; _numericMode.IsChecked = has && row.ResultMode == "数值LIMIT"; _stringMode.IsChecked = has && row.ResultMode == "字符串匹配"; _updating = false; _numericFields.Visibility = !_writeMode && has && row.ResultMode == "数值LIMIT" ? Visibility.Visible : Visibility.Collapsed; _stringFields.Visibility = !_writeMode && has && row.ResultMode == "字符串匹配" ? Visibility.Visible : Visibility.Collapsed; _writeFields.Visibility = _writeMode && has ? Visibility.Visible : Visibility.Collapsed; _needsJudgment.Visibility = _writeMode ? Visibility.Collapsed : Visibility.Visible; }
        private void RefreshFooter() { int selected = _rows.Count(value => value.Use), judged = _rows.Count(value => value.Use && value.NeedsJudgment); _footerSummary.Text = "已选 " + selected + " 项  ·  " + judged + " 项判断"; }
        private ToggleButton ModeButton(string text, string mode) { ToggleButton button = new ToggleButton { Content = text, Height = 36, Style = SegmentStyle(), Margin = new Thickness(0), Cursor = Cursors.Hand }; button.Click += (s, e) => { if (!_updating && Current != null) { Current.ResultMode = mode; RefreshDetailState(); } }; return button; }
        private void Apply(object sender, RoutedEventArgs e) { List<LocatorSignalRow> selected = _rows.Where(value => value.Use).ToList(); if (selected.Count == 0) { MessageBox.Show(this, "请至少选择一个信号。", "信号与判定配置", MessageBoxButton.OK, MessageBoxImage.Information); return; } if (_singleMode && selected.Count != 1) { MessageBox.Show(this, "单信号操作只能选择一个信号。", "信号与判定配置", MessageBoxButton.OK, MessageBoxImage.Information); return; } if (_writeMode && selected.Any(value => string.IsNullOrWhiteSpace(value.ValueText))) { MessageBox.Show(this, "已选择的写入信号必须填写写入值。", "信号与判定配置", MessageBoxButton.OK, MessageBoxImage.Information); return; } foreach (LocatorSignalRow edit in _rows) { LocatorSignalRow original = _sourceRows.FirstOrDefault(value => ReferenceEquals(value.Signal, edit.Signal) || value.Offset == edit.Offset && value.Name == edit.Name); if (original != null) original.CopyConfigurationFrom(edit); } DialogResult = true; }
