        private static Grid FourFieldGrid(string l1, string p1, string l2, string p2, string l3, string p3, string l4, string p4) { Grid grid = new Grid(); for (int i = 0; i < 4; i++) grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); AddField(grid, l1, p1, 0); AddField(grid, l2, p2, 1); AddField(grid, l3, p3, 2); AddField(grid, l4, p4, 3); return grid; }
        private static Grid OneFieldGrid(string label, string property) { Grid grid = new Grid(); grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(160) }); grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(340) }); TextBlock text = new TextBlock { Text = label, VerticalAlignment = VerticalAlignment.Center, Foreground = Text(37, 49, 67) }; grid.Children.Add(text); TextBox box = new TextBox { Height = 32, Padding = new Thickness(8, 5, 8, 5), VerticalContentAlignment = VerticalAlignment.Center }; box.SetBinding(TextBox.TextProperty, new Binding(property) { Mode = BindingMode.TwoWay, UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged }); Grid.SetColumn(box, 1); grid.Children.Add(box); return grid; }
        private static void AddField(Grid grid, string label, string property, int column) { StackPanel panel = new StackPanel { Margin = new Thickness(0, 0, 12, 0) }; panel.Children.Add(new TextBlock { Text = label, Foreground = Text(65, 78, 96), Margin = new Thickness(0, 0, 0, 5) }); Control editor; if (property == "CompareText") { ComboBox combo = new ComboBox { Height = 32, ItemsSource = new[] { "GELE", "GE", "GT", "LE", "LT", "EQ", "NE" } }; combo.SetBinding(Selector.SelectedItemProperty, new Binding(property) { Mode = BindingMode.TwoWay, UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged }); editor = combo; } else { TextBox box = new TextBox { Height = 32, Padding = new Thickness(8, 5, 8, 5) }; box.SetBinding(TextBox.TextProperty, new Binding(property) { Mode = BindingMode.TwoWay, UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged }); editor = box; } panel.Children.Add(editor); Grid.SetColumn(panel, column); grid.Children.Add(panel); }
        private static Button PrimaryButton(string text) { return new Button { Content = text, MinWidth = 116, Height = 34, Padding = new Thickness(16, 5, 16, 5), Margin = new Thickness(8, 0, 0, 0), Background = new SolidColorBrush(Color.FromRgb(24, 112, 224)), Foreground = Brushes.White, BorderBrush = new SolidColorBrush(Color.FromRgb(24, 112, 224)), BorderThickness = new Thickness(1) }; }
        private static Button SecondaryButton(string text) { return new Button { Content = text, MinWidth = 94, Height = 34, Padding = new Thickness(14, 5, 14, 5), Margin = new Thickness(8, 0, 0, 0), Background = Brushes.White, Foreground = Text(52, 67, 88), BorderBrush = Border(), BorderThickness = new Thickness(1) }; }
        private static SolidColorBrush Text(byte r, byte g, byte b) { return new SolidColorBrush(Color.FromRgb(r, g, b)); }
        private static SolidColorBrush Border() { return new SolidColorBrush(Color.FromRgb(211, 221, 234)); }
    }
}
